/**
 * Normalized app projection types — the shape the app printer
 * (`./print-app.ts`), the elements printer, the tf extractor
 * (`../tf.ts` `appFromTf`), and the app-stream orchestrator
 * (`../../extract/app.ts`) all consume.
 *
 * The legacy wire→normalized projection (`normalizeAspect` over the REST
 * `AspectPullResponse`) was deleted with the REST deploy engine; on the
 * pristine-refactor pipeline these shapes are produced from `ei export`
 * HCL streams instead (see `appFromTf`).
 */
import type { AppCategory, AppField, AppStage, AspectType } from "../../../core/types/app.js";
import type { DisplayBlock } from "../../../core/types/display-block.js";
import type { NormalizedAccessPolicy } from "../../access-policy/from-tf.js";
import type { RefExpr } from "../../shared/filters/ast.js";
import type { Filter } from "../../shared/filters/types.js";
import type { ManagedViewSharing } from "../../view/sharing.js";
import type { ListViewDensity, NormalizedManagedViewSort } from "../../view/build.js";
import type { NormalizedRole } from "../../role/from-tf.js";
import type { NormalizedServiceAccount } from "../../service-account/from-tf.js";
import type { CalculationResultType } from "../../field/calculation-types.js";
/**
 * Keyed via `withUniqueKeys`, so two stages named "Review" become
 * `review` / `review2` deterministically. The printer emits each
 * as `stages.<key>`.
 */
export interface NormalizedStage {
    readonly key: string;
    readonly stage: AppStage;
}
export interface NormalizedField {
    readonly key: string;
    readonly field: AppField;
    /** Server-validated output type for a pulled calculated field. */
    readonly calculationType?: CalculationResultType;
    /** Inclusion mode captured from a pulled calculated field. AUTO is omitted. */
    readonly calculationInclude?: "manual" | "both" | {
        readonly picklistFieldId: string;
    };
    /**
     * Side-channel pull annotation for dependent-picklist linkage.
     * Typed-ref `parentField` / `parentValues` on the runtime AppField
     * need real picklist-object references, which aren't available until
     * every sibling field has been projected — and emitting those refs
     * from the printer requires hoisting parent / child fields to
     * top-level `const`s before the `app({...})` literal. We carry
     * just the raw ids here; the printer resolves them against the
     * other entries in the same `NormalizedApp.fields` list at emit
     * time.
     */
    readonly parentLinkage?: {
        /** Parent picklist's field id (same aspect). */
        readonly parentFieldId?: string;
        /** Map of this field's option id → parent option ids. */
        readonly optionParents?: ReadonlyMap<string, readonly string[]>;
        /** Same information reconstructed from Terraform's name-based locals. */
        readonly parentFieldKey?: string;
        /** Child option label -> parent option labels. */
        readonly optionParentLabels?: ReadonlyMap<string, readonly string[]>;
    };
}
/**
 * Snowflake-backed cloud-table mapping for a LINKED element — the terraform
 * dialect's `cloud_mapping_snowflake_*` / `snowflake_hybrid_table` /
 * `title_column_name` / `id_column_name` attributes on `elementum_element`.
 * Real and round-tripped: `elementToTf` re-sends it on build (create-only —
 * the table binding is immutable once set). Reserved for the element pull
 * path; apps with no source-table binding will not populate this slot.
 */
export interface NormalizedCloudConnectionSnowflake {
    readonly kind: "snowflake";
    readonly database?: string;
    readonly schema?: string;
    readonly table?: string;
    readonly hybridTable?: boolean;
    readonly titleColumnName?: string;
    readonly idColumnName?: string;
}
/**
 * Flat projection of one display block. The printer resolves
 * `fieldId` → the field's hoisted-const name and `stageId` → a
 * `stages.<key>` ref at emit time, mirroring how dependent-picklist
 * `parentLinkage` is resolved. Groups carry `childKeys` (the bag keys
 * of their children); children appear as their own entries in the
 * flat list, referenced by those keys.
 */
export interface NormalizedDisplayBlock {
    readonly key: string;
    readonly kind: DisplayBlock["kind"];
    readonly id?: string;
    readonly hidden?: boolean;
    readonly displayLocation?: string;
    /** Set only on top-level blocks (children inherit the group's stage). */
    readonly stageId?: string;
    /** Set on FIELD blocks — the referenced field's id. */
    readonly fieldId?: string;
    readonly name?: string;
    readonly color?: string;
    readonly icon?: string;
    readonly maxColumns?: number;
    readonly sideNavItem?: boolean;
    readonly widgetId?: string;
    readonly channels?: readonly string[];
    readonly channelNames?: Readonly<Record<string, string>>;
    /** GROUP children, in order, by bag key. */
    readonly childKeys?: readonly string[];
}
/**
 * One section of a per-stage layout (`elementum_layout`). `fields` entries
 * are either a canonical system-field key (`"title"`, `"status"`, …) or a
 * custom field's bag key — never a raw id (see `entities/view/from-tf.ts`).
 */
export interface NormalizedLayoutSection {
    readonly type: string;
    readonly displayLocation?: string;
    readonly displayOrder?: number;
    readonly sideNavItem?: boolean;
    readonly name?: string;
    readonly icon?: string;
    readonly color?: string;
    readonly maxColumns?: number;
    readonly fields?: readonly string[];
    readonly widgets?: readonly string[];
}
/** A stage's record-detail layout, keyed by stage key on `NormalizedApp.layouts`. */
export interface NormalizedLayout {
    readonly stageKey: string;
    readonly sections: readonly NormalizedLayoutSection[];
}
/** A saved list view (`elementum_list_view`). `key` is its authoring bag key. */
export interface NormalizedListView extends ManagedViewSharing {
    readonly key: string;
    readonly name: string;
    readonly columns: readonly string[];
    readonly allowRecordCreation?: boolean;
    readonly density?: ListViewDensity;
    readonly rows?: number;
    /** Opaque JSON pass-through (see `entities/view/from-tf.ts` for why). */
    readonly filter?: Filter<RefExpr, RefExpr>;
    readonly sort?: NormalizedManagedViewSort;
}
/** An agent-powered view (`elementum_agent_view`). */
export interface NormalizedAgentView extends ManagedViewSharing {
    readonly key: string;
    readonly name: string;
    readonly agentKey: string;
    readonly allowRecordCreation?: boolean;
    readonly filter?: Filter<RefExpr, RefExpr>;
    readonly sort?: NormalizedManagedViewSort;
    readonly displayOrder?: number;
}
/** A calendar view (`elementum_calendar_view`). */
export interface NormalizedCalendarView extends ManagedViewSharing {
    readonly key: string;
    readonly name: string;
    readonly columns: readonly string[];
    readonly displayByField?: string;
    readonly allowRecordCreation?: boolean;
    readonly filter?: Filter<RefExpr, RefExpr>;
    readonly sort?: NormalizedManagedViewSort;
}
/** A kanban view (`elementum_kanban_view`). */
export interface NormalizedKanbanView extends NormalizedCalendarView {
    readonly allowedFilterFields?: readonly string[];
}
export interface NormalizedDashboard {
    readonly key: string;
    readonly name: string;
    readonly favorite?: boolean;
    readonly tags?: readonly string[];
    readonly widgets?: readonly NormalizedDashboardWidget[];
}
export type NormalizedDashboardWidget = {
    readonly key: string;
    readonly name: string;
    readonly size: string;
    readonly color?: string;
    readonly icon?: string;
    readonly type: "records";
    readonly target: NormalizedWidgetRef & {
        readonly kind: "app" | "element";
    };
    readonly filter?: Filter<RefExpr, RefExpr>;
} | {
    readonly key: string;
    readonly name: string;
    readonly size: string;
    readonly color?: string;
    readonly icon?: string;
    readonly type: "chart";
    readonly chartKey: string;
};
export interface NormalizedWidgetRef {
    readonly kind: "app" | "element" | "automation" | "field" | "recordIdentity";
    readonly key: string;
    readonly name: string;
    readonly parent?: string;
    readonly fieldType?: string;
    readonly target?: NormalizedWidgetRef;
    /** A foreign app/element target resolved by namespace rather than a display-name lookup. */
    readonly namespace?: string;
    /** `key`/`name` are the target's real pulled catalog identity - print via appRef()/elementRef(). */
    readonly catalogRef?: true;
}
export interface NormalizedWidgetButtonStyle {
    readonly buttonType: "INLINE" | "PRIMARY" | "SECONDARY";
    readonly color?: string;
    readonly icon?: string;
    readonly fullWidth?: boolean;
}
export type NormalizedWidget = {
    readonly key: string;
    readonly type: "relatedRecords";
    readonly name: string;
    readonly target: NormalizedWidgetRef | string;
    readonly columns?: readonly (NormalizedWidgetRef | string)[];
    readonly rows?: number;
} | ({
    readonly key: string;
    readonly type: "linkRecords";
    readonly name: string;
    readonly target: NormalizedWidgetRef | string;
    readonly columns?: readonly (NormalizedWidgetRef | string)[];
    readonly rows?: number;
    readonly filter?: Filter<RefExpr, RefExpr>;
} & NormalizedWidgetButtonStyle) | ({
    readonly key: string;
    readonly type: "createRecord";
    readonly name: string;
    readonly target: NormalizedWidgetRef | string;
} & NormalizedWidgetButtonStyle) | ({
    readonly key: string;
    readonly type: "runAutomation";
    readonly name: string;
    readonly automation: NormalizedWidgetRef | string;
    readonly parameters?: readonly {
        readonly name: string;
        readonly fieldType: string;
        readonly multiple: boolean;
        readonly required: boolean;
        readonly field?: NormalizedWidgetRef | string;
        readonly value?: string;
    }[];
} & NormalizedWidgetButtonStyle);
/** A view that embeds one of the owning aspect's dashboards. */
export interface NormalizedDashboardView extends ManagedViewSharing {
    readonly key: string;
    readonly name: string;
    readonly dashboardKey: string;
    readonly allowRecordCreation?: boolean;
    readonly filter?: Filter<RefExpr, RefExpr>;
    readonly sort?: NormalizedManagedViewSort;
}
export interface NormalizedRecordCreateFormSection {
    readonly name: string;
    readonly fields: readonly string[];
    readonly agentKey?: string;
    readonly icon?: string;
    readonly color?: string;
    readonly displayOrder?: number;
    readonly displayLocation?: string;
    readonly sideNavItem?: boolean;
    readonly hidden?: boolean;
    readonly maxColumns?: number;
}
export interface NormalizedRecordCreateForm {
    readonly sections: readonly NormalizedRecordCreateFormSection[];
}
export interface PulledDynamicLayoutRef {
    readonly __pulledRef: "field" | "automation" | "agent" | "app" | "element";
    readonly key: string;
    readonly parent?: string;
    readonly name?: string;
    /** A foreign app/element target resolved by namespace rather than a display-name lookup. */
    readonly namespace?: string;
}
export interface NormalizedDynamicLayout {
    readonly key: string;
    /** Camel-case authoring value with pulled-reference markers in token positions. */
    readonly layout: Readonly<Record<string, unknown>>;
}
export interface PulledRelationshipRef {
    readonly kind: "app" | "element" | "table" | "field" | "tableColumn" | "recordIdentity";
    readonly key: string;
    readonly name: string;
    readonly parent?: string;
    readonly fieldType?: string;
    readonly tfLabel?: string;
    readonly managed?: boolean;
    /** The recursive pull resolved this reference to an on-disk generated catalog token. */
    readonly catalogRef?: boolean;
    readonly namespace?: string;
    readonly parentKind?: "app" | "element";
    readonly parentName?: string;
    readonly parentNamespace?: string;
    readonly target?: PulledRelationshipRef;
}
export interface NormalizedRelationship {
    readonly key: string;
    readonly target: PulledRelationshipRef;
    readonly columns: readonly {
        readonly field: string;
        readonly relatedField: PulledRelationshipRef;
    }[];
    readonly filter?: NormalizedAccessPolicy["filter"];
}
/**
 * Normalized aspect ready for `print-app.ts`. Carries the round-
 * trip surface plus any cataloged metadata (handle for export
 * binding). The wire bag fields agentsV2 / automations / search
 * tables are not pulled here — those have their own pull scripts
 * (`pull-agent`, `pull-automation`).
 *
 * `cloudLinkId`, `commentsEnabled`, and `cloudConnection` round-trip
 * the metadata the discovery endpoints don't surface. They live on
 * the normalized shape today; the printer wires them into the
 * emitted `app({...})` / `element({...})` source as the
 * matching authoring slots land.
 */
export interface NormalizedApp {
    readonly id: string;
    readonly name: string;
    readonly description?: string;
    readonly namespace?: string;
    readonly icon?: string;
    readonly color?: string;
    readonly type?: AspectType;
    readonly category?: AppCategory;
    /** camelCased identifier for the export binding and EDK refName. */
    readonly refName: string;
    /** Backend app/element handle authored into app({ handle }). */
    readonly backendHandle: string;
    readonly fields: readonly NormalizedField[];
    readonly stages: readonly NormalizedStage[];
    readonly cloudLinkId?: string;
    readonly cloudLinkClientHandle?: string;
    readonly commentsEnabled?: boolean;
    readonly lockStages?: boolean;
    readonly cloudOptions?: {
        readonly snowflake?: {
            readonly hybridTable?: boolean;
        };
    };
    readonly cloudConnection?: NormalizedCloudConnectionSnowflake;
    /** Record-view (LAYOUT) display blocks, flat with `childKeys` linkage. */
    readonly displayBlocks?: readonly NormalizedDisplayBlock[];
    /** New-record-form (CREATE) display blocks. */
    readonly recordCreateDisplayBlocks?: readonly NormalizedDisplayBlock[];
    /** Per-stage record layouts (terraform-path `elementum_layout`), keyed by `stageKey`. */
    readonly layouts?: readonly NormalizedLayout[];
    /** Saved list views (`elementum_list_view`). */
    readonly listViews?: readonly NormalizedListView[];
    /** Calendar views (`elementum_calendar_view`). */
    readonly calendarViews?: readonly NormalizedCalendarView[];
    /** Kanban views (`elementum_kanban_view`). */
    readonly kanbanViews?: readonly NormalizedKanbanView[];
    readonly dashboardViews?: readonly NormalizedDashboardView[];
    readonly dashboards?: readonly NormalizedDashboard[];
    readonly widgets?: readonly NormalizedWidget[];
    /** Agent-powered record views (`elementum_agent_view`). */
    readonly agentViews?: readonly NormalizedAgentView[];
    /** New-record form (`elementum_record_create_form`). */
    readonly recordCreateForm?: NormalizedRecordCreateForm;
    readonly dynamicLayouts?: readonly NormalizedDynamicLayout[];
    readonly relationships?: readonly NormalizedRelationship[];
    /** Display order of `listViews`, by key (`elementum_managed_view_order`). */
    readonly viewOrder?: readonly string[];
    /** App/element-level sharing & row-level-security policies (`elementum_access_policy`), in export order. */
    readonly accessPolicies?: readonly NormalizedAccessPolicy[];
    /** Custom roles only; managed roles are represented by data lookups. */
    readonly roles?: readonly NormalizedRole[];
    readonly serviceAccounts?: readonly NormalizedServiceAccount[];
}
